import{ARENA_WIDTH,MIN_X,MAX_X}from'./movement.mjs';
export const TIMINGS={dash:[.025,.035,.05,.07,.045,.05],punch:[.05,.08,.06,.09,.08,.10],kick:[.08,.12,.08,.12,.12,.13],dodge:[.04,.07,.10,.18,.09,.13],jump:[.05,.10,.16,.25,.13,.12],block:[.04,.06,.10,.10,.08,.08]};
export const TOTAL=Object.fromEntries(Object.entries(TIMINGS).map(([k,v])=>[k,v.reduce((a,b)=>a+b,0)]));
export function frameAt(type,t){let sum=0;for(let i=0;i<6;i++){sum+=TIMINGS[type][i];if(t<sum)return i}return 5}
export class Fight{
 constructor(random=Math.random){this.random=random;this.phase='menu';this.paused=false;this.events=[];this.fighters=[];this.mode='cpu';this.difficulty='normal';this.wins=[0,0];this.round=0;this.clock=0;this.timer=60;this.phaseT=0;this.winner=null;this.roundWinner=null;this.aiT=0;this.aiInput={move:0,block:false};}
 emit(type,data={}){this.events.push({type,...data})}
 start({mode='cpu',character=0,difficulty='normal'}={}){this.mode=mode;this.character=character;this.difficulty=difficulty;this.wins=[0,0];this.round=0;this.clock=0;this.winner=null;this.paused=false;this.newRound()}
 newRound(){this.round++;this.fighters=[0,1].map(i=>({id:i,char:i?1-this.character:this.character,x:ARENA_WIDTH/2+(i?250:-250),dir:i?-1:1,hp:100,energy:100,action:'idle',t:0,frame:0,hit:false,stun:0,cooldown:0,walk:0,combo:0,lastHit:-10,dashDir:0}));this.timer=60;this.phase='countdown';this.phaseT=0;this.roundWinner=null;this.aiT=.5;this.aiInput={move:0,block:false};this.emit('round',{round:this.round})}
 action(id,type){const f=this.fighters[id];if(!f||this.phase!=='fight'||this.paused||f.stun>0||f.cooldown>0||f.action!=='idle'||!TIMINGS[type])return false;if(type==='dodge'||type==='dash'){const cost=type==='dash'?14:28;if(f.energy<cost){this.emit('empty',{id});return false}f.energy-=cost}f.action=type;f.t=0;f.frame=0;f.hit=false;if(type==='punch'||type==='kick')this.emit('swing',{id});return true}
 dash(id,direction){if(direction!==1&&direction!==-1)return false;const ok=this.action(id,'dash');if(ok){this.fighters[id].dashDir=direction;this.emit('dash',{id,direction})}return ok}
 endRound(winner){if(this.phase!=='fight')return;this.phase='roundOver';this.phaseT=0;this.roundWinner=winner;if(winner!==null)this.wins[winner]++;if(this.wins.some(w=>w>=2)){this.winner=this.wins[0]>=2?0:1;this.phase='matchOver'}this.emit('roundEnd',{winner,match:this.phase==='matchOver'})}
 hit(a,b,contact=false){let f=this.fighters[a],target=this.fighters[b],range=f.action==='kick'?245:210;if(!contact&&Math.abs(f.x-target.x)>range)return false;if(target.action==='dodge'&&target.frame>=2&&target.frame<=3){this.emit('evade',{id:b});return false}if(target.action==='jump'&&target.frame>=2&&target.frame<=3){this.emit('evade',{id:b});return false}const block=target.action==='block'&&target.frame>=2&&target.frame<=3&&target.dir===-f.dir;const damage=block?2:f.action==='kick'?15:9;target.hp=Math.max(0,target.hp-damage);target.energy=Math.max(0,target.energy-(block?9:0));target.stun=block?.06:.19;if(target.action==='dash'){target.action='idle';target.frame=0;target.t=0}target.x=Math.max(MIN_X,Math.min(MAX_X,target.x+f.dir*(block?5:18)));if(!block){f.combo=this.clock-f.lastHit<1.05?f.combo+1:1;f.lastHit=this.clock;f.energy=Math.min(100,f.energy+4)}this.emit(block?'block':'hit',{id:b,attacker:a,x:target.x,y:330,damage,combo:f.combo});return true}
 cpu(dt){const f=this.fighters[1],other=this.fighters[0],dist=Math.abs(f.x-other.x),hard=this.difficulty==='hard';this.aiT-=dt;if(this.aiT>0)return this.aiInput;this.aiT=(hard?.13:.26)+this.random()*(hard?.22:.35);const danger=['punch','kick'].includes(other.action)&&dist<260;this.aiInput={move:dist>190?f.dir:dist<150?-f.dir:0,block:false};if(danger&&this.random()<(hard?.8:.55)){const n=this.random();if(n<.45){this.aiInput.block=true;this.action(1,'block')}else this.action(1,n<.75?'dodge':'jump')}else if(dist>420&&this.random()<(hard?.5:.3)){this.dash(1,f.dir)}else if(dist<250&&this.random()<.9){this.action(1,this.random()<.42?'kick':'punch')}else if(dist>290&&this.random()<.12)this.action(1,'jump');return this.aiInput}
 update(dt,inputs=[{},{}]){if(this.paused||this.phase==='menu'||this.phase==='matchOver')return;dt=Math.min(dt,.05);this.clock+=dt;this.phaseT+=dt;if(this.phase==='countdown'){if(this.phaseT>=2.6){this.phase='fight';this.phaseT=0;this.emit('fight')}return}if(this.phase==='roundOver'){if(this.phaseT>=2.6)this.newRound();return}let controls=[inputs[0]||{},inputs[1]||{}];if(this.mode==='cpu')controls[1]=this.cpu(dt);this.timer=Math.max(0,this.timer-dt);
 this.fighters.forEach((f,i)=>{const b=this.fighters[1-i],input=controls[i];f.dir=b.x>f.x?1:-1;f.energy=Math.min(100,f.energy+dt*10);f.stun=Math.max(0,f.stun-dt);f.cooldown=Math.max(0,f.cooldown-dt);if(f.action==='idle'&&input.block)this.action(i,'block');let moving=Number(input.move)||0;if(f.stun===0&&((f.action==='idle'&&!input.block)||f.action==='jump')){f.x+=moving*(f.action==='jump'?130:220)*dt;f.walk=moving?f.walk+dt:0}else f.walk=0;
 if(f.action==='dash'&&f.stun===0)f.x+=f.dashDir*780*dt;
 if(f.action!=='idle'){f.t+=dt;f.frame=frameAt(f.action,f.t);if(f.action==='block'&&input.block&&f.frame>=3&&f.energy>0){f.t=.20;f.frame=3}if(f.action==='dodge'&&f.frame===3)f.x-=f.dir*95*dt;if(f.t>=TOTAL[f.action]){const prev=f.action;f.action='idle';f.t=0;f.frame=0;f.cooldown=prev==='dodge'?.22:prev==='dash'?.18:.06}}f.x=Math.max(MIN_X,Math.min(MAX_X,f.x))});
 let[a,b]=this.fighters;const gap=b.x-a.x;if(Math.abs(gap)<158){let mid=Math.max(MIN_X+79,Math.min(MAX_X-79,(a.x+b.x)/2)),dir=gap>=0?1:-1;a.x=mid-dir*79;b.x=mid+dir*79}
 // Resolve both active strikes before checking KO, allowing a simultaneous draw.
 const strikes=this.fighters.map((f,i)=>({id:i,active:['punch','kick'].includes(f.action)&&f.frame>=3&&!f.hit,inRange:Math.abs(f.x-this.fighters[1-i].x)<=(f.action==='kick'?245:210)}));for(const strike of strikes){if(strike.active){this.fighters[strike.id].hit=true;if(strike.inRange)this.hit(strike.id,1-strike.id,true)}}
 const dead=this.fighters.map(f=>f.hp<=0);if(dead[0]||dead[1])this.endRound(dead[0]&&dead[1]?null:dead[0]?1:0);else if(this.timer===0)this.endRound(a.hp===b.hp?null:a.hp>b.hp?0:1)}
}
